import{at as e,it as t,n,vt as r}from"./chunks/framework.aIoRY1TZ.js";var i=JSON.parse(`{"title":"micro509/jose","description":"","frontmatter":{"title":"micro509/jose","packageVersion":"0.17.1"},"headers":[],"relativePath":"api/jose.md","filePath":"site/api/jose.md","lastUpdated":0}`),a={name:`api/jose.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="micro509-jose" tabindex="-1"><code>micro509/jose</code> <a class="header-anchor" href="#micro509-jose" aria-label="Permalink to “micro509/jose”">​</a></h1><p>Optional JOSE surface: signed compact JWS and JWT (RS256), JWK Sets, and opt-in remote JWKS resolution. Importing this entrypoint performs no network access.</p><p>Start with <a href="/v0.17.1/api/fn/verifyJwt"><code>verifyJwt</code></a> for tokens, <a href="/v0.17.1/api/fn/createJwksKeyResolver"><code>createJwksKeyResolver</code></a> for a local JWK Set, and <a href="/v0.17.1/api/fn/createRemoteJwksKeyResolver"><code>createRemoteJwksKeyResolver</code></a> to read keys from a trusted URL.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><span id="fn-createjwkskeyresolver"></span><a href="/v0.17.1/api/fn/createJwksKeyResolver"><code>createJwksKeyResolver</code></a> — Creates a key resolver over a fixed JWK Set.</li><li><span id="fn-importjwkentry"></span><a href="/v0.17.1/api/fn/importJwkEntry"><code>importJwkEntry</code></a> — Imports a selected entry as a verify-only RS256 <code>CryptoKey</code>.</li><li><span id="fn-parsejwks"></span><a href="/v0.17.1/api/fn/parseJwks"><code>parseJwks</code></a> — Parses a JWK Set document.</li><li><span id="fn-selectjwk"></span><a href="/v0.17.1/api/fn/selectJwk"><code>selectJwk</code></a> — Selects the one key of a set that can verify <code>selector</code>.</li><li><span id="fn-parsecompactjws"></span><a href="/v0.17.1/api/fn/parseCompactJws"><code>parseCompactJws</code></a> — Parses a compact JWS without checking its signature.</li><li><span id="fn-signcompactjws"></span><a href="/v0.17.1/api/fn/signCompactJws"><code>signCompactJws</code></a> — Signs a compact JWS with an existing private <code>CryptoKey</code>.</li><li><span id="fn-verifycompactjws"></span><a href="/v0.17.1/api/fn/verifyCompactJws"><code>verifyCompactJws</code></a> — Verifies a compact JWS.</li><li><span id="fn-decodejwtunverified"></span><a href="/v0.17.1/api/fn/decodeJwtUnverified"><code>decodeJwtUnverified</code></a> — Decodes a JWT without checking its signature. Every field of the result is unauthenticated.</li><li><span id="fn-signjwt"></span><a href="/v0.17.1/api/fn/signJwt"><code>signJwt</code></a> — Signs a JWT. The header carries <code>typ: &quot;JWT&quot;</code> unless <code>header.typ</code> says otherwise.</li><li><span id="fn-verifyjwt"></span><a href="/v0.17.1/api/fn/verifyJwt"><code>verifyJwt</code></a> — Verifies a JWT: the signature and <code>tokenType</code> policy as <a href="/v0.17.1/api/fn/verifyCompactJws"><code>verifyCompactJws</code></a> applies</li><li><span id="fn-createremotejwkskeyresolver"></span><a href="/v0.17.1/api/fn/createRemoteJwksKeyResolver"><code>createRemoteJwksKeyResolver</code></a> — Creates a key resolver that reads a JWK Set from one trusted URL.</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><ul><li><span id="type-jsonobject"></span><a href="/v0.17.1/api/type/JsonObject"><code>JsonObject</code></a> — A parsed JSON object.</li><li><span id="type-jsonvalue"></span><a href="/v0.17.1/api/type/JsonValue"><code>JsonValue</code></a> — A parsed JSON value. Objects are plain records whose members are all own data properties.</li><li><span id="type-joseerrorcode"></span><a href="/v0.17.1/api/type/JoseErrorCode"><code>JoseErrorCode</code></a> — Every code a JOSE API reports.</li><li><span id="type-joseerrordetails"></span><a href="/v0.17.1/api/type/JoseErrorDetails"><code>JoseErrorDetails</code></a> — Structured context for a failure. Holds names and short identifiers only, never token</li><li><span id="type-joseerrorresult"></span><a href="/v0.17.1/api/type/JoseErrorResult"><code>JoseErrorResult</code></a> — A flattened failed result carrying a <a href="/v0.17.1/api/type/JoseFailure"><code>JoseFailure</code></a>.</li><li><span id="type-josefailure"></span><a href="/v0.17.1/api/type/JoseFailure"><code>JoseFailure</code></a> — Failure payload of the JOSE APIs.</li><li><span id="type-joseresult"></span><a href="/v0.17.1/api/type/JoseResult"><code>JoseResult</code></a> — Success-or-failure result of a JOSE API.</li><li><span id="type-jwsparseerrorcode"></span><a href="/v0.17.1/api/type/JwsParseErrorCode"><code>JwsParseErrorCode</code></a> — Reasons a compact serialization is refused before any signature is checked.</li><li><span id="type-jwspolicyerrorcode"></span><a href="/v0.17.1/api/type/JwsPolicyErrorCode"><code>JwsPolicyErrorCode</code></a> — Reasons a well-formed token is refused by the verification policy or its signature.</li><li><span id="type-jwtclaimserrorcode"></span><a href="/v0.17.1/api/type/JwtClaimsErrorCode"><code>JwtClaimsErrorCode</code></a> — Reasons a signature-verified token fails the claims policy.</li><li><span id="type-keyresolutionerrorcode"></span><a href="/v0.17.1/api/type/KeyResolutionErrorCode"><code>KeyResolutionErrorCode</code></a> — Reasons a signing key cannot be resolved for a token.</li><li><span id="type-verifyjwserrorcode"></span><a href="/v0.17.1/api/type/VerifyJwsErrorCode"><code>VerifyJwsErrorCode</code></a> — Failure codes of <a href="/v0.17.1/api/fn/verifyCompactJws"><code>verifyCompactJws</code></a>.</li><li><span id="type-verifyjwterrorcode"></span><a href="/v0.17.1/api/type/VerifyJwtErrorCode"><code>VerifyJwtErrorCode</code></a> — Failure codes of <a href="/v0.17.1/api/fn/verifyJwt"><code>verifyJwt</code></a>.</li><li><span id="type-jwkentry"></span><a href="/v0.17.1/api/type/JwkEntry"><code>JwkEntry</code></a> — One key of a JWK Set.</li><li><span id="type-jwkentrybase"></span><a href="/v0.17.1/api/type/JwkEntryBase"><code>JwkEntryBase</code></a> — Members shared by every parsed entry.</li><li><span id="type-jwkmetadata"></span><a href="/v0.17.1/api/type/JwkMetadata"><code>JwkMetadata</code></a> — Members every JWK entry carries beside its key material.</li><li><span id="type-jwkselector"></span><a href="/v0.17.1/api/type/JwkSelector"><code>JwkSelector</code></a> — What <a href="/v0.17.1/api/fn/selectJwk"><code>selectJwk</code></a> matches against.</li><li><span id="type-jwks"></span><a href="/v0.17.1/api/type/Jwks"><code>Jwks</code></a> — A parsed JWK Set.</li><li><span id="type-jwkslimits"></span><a href="/v0.17.1/api/type/JwksLimits"><code>JwksLimits</code></a> — Bounds applied while parsing a JWK Set.</li><li><span id="type-parsejwkserrorcode"></span><a href="/v0.17.1/api/type/ParseJwksErrorCode"><code>ParseJwksErrorCode</code></a> — Codes <a href="/v0.17.1/api/fn/parseJwks"><code>parseJwks</code></a> returns.</li><li><span id="type-rsajwkentry"></span><a href="/v0.17.1/api/type/RsaJwkEntry"><code>RsaJwkEntry</code></a> — An RSA public key entry.</li><li><span id="type-unsupportedjwkentry"></span><a href="/v0.17.1/api/type/UnsupportedJwkEntry"><code>UnsupportedJwkEntry</code></a> — An entry this module never selects: a <code>kty</code> other than <code>RSA</code>, or an entry with missing or</li><li><span id="type-joselimits"></span><a href="/v0.17.1/api/type/JoseLimits"><code>JoseLimits</code></a> — Size and structure bounds enforced before any expensive parsing.</li><li><span id="type-jwsalgorithm"></span><a href="/v0.17.1/api/type/JwsAlgorithm"><code>JwsAlgorithm</code></a> — Signature algorithms this module signs and verifies.</li><li><span id="type-jwsheader"></span><a href="/v0.17.1/api/type/JwsHeader"><code>JwsHeader</code></a> — A protected header. Every member the token carried stays reachable through <code>members</code>.</li><li><span id="type-jwsheaderinput"></span><a href="/v0.17.1/api/type/JwsHeaderInput"><code>JwsHeaderInput</code></a> — Header members <a href="/v0.17.1/api/fn/signCompactJws"><code>signCompactJws</code></a> sets beside <code>alg</code>.</li><li><span id="type-jwskeyrequest"></span><a href="/v0.17.1/api/type/JwsKeyRequest"><code>JwsKeyRequest</code></a> — What a key resolver is asked for. The header is unauthenticated.</li><li><span id="type-jwskeyresolver"></span><a href="/v0.17.1/api/type/JwsKeyResolver"><code>JwsKeyResolver</code></a> — Supplies the verification key for a token.</li><li><span id="type-signjoseerrorcode"></span><a href="/v0.17.1/api/type/SignJoseErrorCode"><code>SignJoseErrorCode</code></a> — Codes <a href="/v0.17.1/api/fn/signCompactJws"><code>signCompactJws</code></a> and <a href="/v0.17.1/api/fn/signJwt"><code>signJwt</code></a> throw.</li><li><span id="type-signjwsinput"></span><a href="/v0.17.1/api/type/SignJwsInput"><code>SignJwsInput</code></a> — Input for <a href="/v0.17.1/api/fn/signCompactJws"><code>signCompactJws</code></a>.</li><li><span id="type-tokentypepolicy"></span><a href="/v0.17.1/api/type/TokenTypePolicy"><code>TokenTypePolicy</code></a> — Expectation for the <code>typ</code> header (RFC 7515 §4.1.9, RFC 8725 §3.11).</li><li><span id="type-unchecked"></span><a href="/v0.17.1/api/type/Unchecked"><code>Unchecked</code></a> — Marks a policy dimension as deliberately not checked.</li><li><span id="type-unverifiedjws"></span><a href="/v0.17.1/api/type/UnverifiedJws"><code>UnverifiedJws</code></a> — A parsed token whose signature has not been checked. Nothing in it is trustworthy until</li><li><span id="type-verifiedjws"></span><a href="/v0.17.1/api/type/VerifiedJws"><code>VerifiedJws</code></a> — A token whose signature verified under the caller&#39;s algorithm and key policy.</li><li><span id="type-verifyjwsoptions"></span><a href="/v0.17.1/api/type/VerifyJwsOptions"><code>VerifyJwsOptions</code></a> — Options for <a href="/v0.17.1/api/fn/verifyCompactJws"><code>verifyCompactJws</code></a>.</li><li><span id="type-futureissuedatpolicy"></span><a href="/v0.17.1/api/type/FutureIssuedAtPolicy"><code>FutureIssuedAtPolicy</code></a> — Whether an <code>iat</code> later than the clock is accepted.</li><li><span id="type-jwtclaimspolicy"></span><a href="/v0.17.1/api/type/JwtClaimsPolicy"><code>JwtClaimsPolicy</code></a> — Claims policy for <a href="/v0.17.1/api/fn/verifyJwt"><code>verifyJwt</code></a>. Application authorization stays with the caller.</li><li><span id="type-registeredclaims"></span><a href="/v0.17.1/api/type/RegisteredClaims"><code>RegisteredClaims</code></a> — The RFC 7519 §4.1 registered claims, each checked against its defined type.</li><li><span id="type-signjwtinput"></span><a href="/v0.17.1/api/type/SignJwtInput"><code>SignJwtInput</code></a> — Input for <a href="/v0.17.1/api/fn/signJwt"><code>signJwt</code></a>.</li><li><span id="type-unverifiedjwt"></span><a href="/v0.17.1/api/type/UnverifiedJwt"><code>UnverifiedJwt</code></a> — A decoded JWT whose signature has not been checked.</li><li><span id="type-verifiedjwt"></span><a href="/v0.17.1/api/type/VerifiedJwt"><code>VerifiedJwt</code></a> — A JWT whose signature and claims both passed the caller&#39;s policy.</li><li><span id="type-verifyjwtoptions"></span><a href="/v0.17.1/api/type/VerifyJwtOptions"><code>VerifyJwtOptions</code></a> — Options for <a href="/v0.17.1/api/fn/verifyJwt"><code>verifyJwt</code></a>.</li><li><span id="type-jwksrequestinit"></span><a href="/v0.17.1/api/type/JwksRequestInit"><code>JwksRequestInit</code></a> — The request <a href="/v0.17.1/api/type/JwksTransport"><code>JwksTransport</code></a> must issue.</li><li><span id="type-jwkstransport"></span><a href="/v0.17.1/api/type/JwksTransport"><code>JwksTransport</code></a> — Performs one HTTP request. <code>fetch</code> satisfies this type. Supply another to route through a proxy,</li><li><span id="type-remotejwksconfig"></span><a href="/v0.17.1/api/type/RemoteJwksConfig"><code>RemoteJwksConfig</code></a> — Configuration of <a href="/v0.17.1/api/fn/createRemoteJwksKeyResolver"><code>createRemoteJwksKeyResolver</code></a>.</li><li><span id="type-remotejwksconfigerrorcode"></span><a href="/v0.17.1/api/type/RemoteJwksConfigErrorCode"><code>RemoteJwksConfigErrorCode</code></a> — Codes <a href="/v0.17.1/api/fn/createRemoteJwksKeyResolver"><code>createRemoteJwksKeyResolver</code></a> throws for unusable configuration.</li><li><span id="type-remotejwksredirectpolicy"></span><a href="/v0.17.1/api/type/RemoteJwksRedirectPolicy"><code>RemoteJwksRedirectPolicy</code></a> — Redirect handling for a remote JWK Set. By default redirects are refused.</li></ul><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><ul><li><span id="var-default_jwks_limits"></span><a href="/v0.17.1/api/var/DEFAULT_JWKS_LIMITS"><code>DEFAULT_JWKS_LIMITS</code></a> — The limits applied when a caller supplies none.</li><li><span id="var-default_jose_limits"></span><a href="/v0.17.1/api/var/DEFAULT_JOSE_LIMITS"><code>DEFAULT_JOSE_LIMITS</code></a> — The limits applied when a caller supplies none.</li><li><span id="var-jws_algorithms"></span><a href="/v0.17.1/api/var/JWS_ALGORITHMS"><code>JWS_ALGORITHMS</code></a> — Every <a href="/v0.17.1/api/type/JwsAlgorithm"><code>JwsAlgorithm</code></a>.</li><li><span id="var-min_rs256_modulus_bits"></span><a href="/v0.17.1/api/var/MIN_RS256_MODULUS_BITS"><code>MIN_RS256_MODULUS_BITS</code></a> — Smallest RSA modulus RS256 accepts (RFC 7518 §3.3).</li><li><span id="var-max_clock_tolerance_seconds"></span><a href="/v0.17.1/api/var/MAX_CLOCK_TOLERANCE_SECONDS"><code>MAX_CLOCK_TOLERANCE_SECONDS</code></a> — Largest clock tolerance <a href="/v0.17.1/api/type/JwtClaimsPolicy"><code>JwtClaimsPolicy.clockToleranceSeconds</code></a> accepts.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};